// src/router/index.js - ROUTER FULL & PERFECT
import { createRouter, createWebHistory } from "vue-router";

import LoginPage from "../views/LoginPage.vue";
import DashboardPage from "../views/DashboardPage.vue";
import InputAnak from "../views/InputAnak.vue";
import GrafikPertumbuhan from "../views/GrafikPertumbuhan.vue";
import KalkulatorGizi from "../views/KalkulatorGizi.vue";
import VideoEdukasi from "../views/VideoEdukasi.vue";

const routes = [
  {
    path: "/",
    component: LoginPage,
  },
  {
    path: "/dashboard",
    component: DashboardPage,
    meta: { requiresAuth: true },
    children: [
      // Semua menu sesuai DashboardPage.vue
      { path: "input-anak", component: InputAnak },
      { path: "video-edukasi", component: VideoEdukasi },
      { path: "kalkulator-gizi", component: KalkulatorGizi },
      { path: "grafik-bb-tb", component: GrafikPertumbuhan },
      { path: "grafik-pertumbuhan", component: GrafikPertumbuhan }, // Alias
    ],
  },
];

const router = createRouter({
  history: createWebHistory(),
  routes,
});

// 🛡️ Auth Guard - Pastikan login dulu baru dashboard
router.beforeEach((to, from, next) => {
  const isLogin = localStorage.getItem("isLogin");

  // Kalau mau ke dashboard tapi belum login → balik ke login
  if (to.meta.requiresAuth && !isLogin) {
    next("/");
  }
  // Kalau udah login dan mau ke login → redirect dashboard
  else if (to.path === "/" && isLogin) {
    next("/dashboard");
  }
  // Lainnya boleh lewat
  else {
    next();
  }
});

export default router;
