<template>
  <div class="growth-dashboard">
    <!-- Header -->
    <header class="page-header">
      <div class="header-left">
        <div class="page-icon">📈</div>
        <div>
          <h1 class="page-title">Grafik Pertumbuhan</h1>
          <p class="page-subtitle">Monitor BB & TB anak secara real-time</p>
        </div>
      </div>

      <!-- Controls -->
      <div class="controls-panel">
        <div class="child-selector">
          <label>👶 Pilih Anak</label>
          <select v-model="selectedChild" @change="loadChildData">
            <option value="">-- Pilih Anak --</option>
            <option
              v-for="child in childrenData"
              :key="child.id"
              :value="child.id"
            >
              {{ child.name }} • {{ child.age }} bulan
            </option>
          </select>
        </div>

        <div class="chart-toggle">
          <button
            :class="['toggle-btn', { active: chartView === 'bb' }]"
            @click="setChartView('bb')"
          >
            ⚖️ BB/U
          </button>
          <button
            :class="['toggle-btn', { active: chartView === 'tb' }]"
            @click="setChartView('tb')"
          >
            📏 TB/U
          </button>
          <button
            :class="['toggle-btn', { active: chartView === 'dual' }]"
            @click="setChartView('dual')"
          >
            📊 Dual
          </button>
        </div>
      </div>
    </header>

    <!-- Charts Section -->
    <div class="charts-section" v-if="selectedChild">
      <!-- Single Chart View -->
      <div v-if="chartView !== 'dual'" class="chart-container">
        <div class="chart-header">
          <h3>
            {{ chartView === "bb" ? "Berat Badan/Umur" : "Tinggi Badan/Umur" }}
          </h3>
          <div class="chart-stats">
            <span class="stat-item">
              Terakhir:
              {{
                latestMeasurement?.[chartView === "bb" ? "bb" : "tb"]?.toFixed(
                  2
                ) || 0
              }}
              {{ chartView === "bb" ? "kg" : "cm" }}
            </span>
            <span class="stat-item status-{{ latestStatus }}">
              {{ latestStatusLabel }}
            </span>
          </div>
        </div>
        <div class="chart-wrapper">
          <canvas ref="growthChart"></canvas>
        </div>
      </div>

      <!-- Dual Chart View -->
      <div v-else class="dual-charts">
        <div class="chart-item">
          <div class="chart-header">
            <h4>⚖️ Berat Badan</h4>
            <span class="stat-value">{{ latestBB?.toFixed(2) }} kg</span>
          </div>
          <canvas ref="bbChart"></canvas>
        </div>
        <div class="chart-item">
          <div class="chart-header">
            <h4>📏 Tinggi Badan</h4>
            <span class="stat-value">{{ latestTB?.toFixed(1) }} cm</span>
          </div>
          <canvas ref="tbChart"></canvas>
        </div>
      </div>
    </div>

    <!-- No Data State -->
    <div v-else class="no-data-state" :class="{ selected: selectedChild }">
      <div class="no-data-icon">📊</div>
      <h3>Pilih anak untuk melihat grafik pertumbuhan</h3>
      <p>Data BB & TB akan ditampilkan dalam grafik interaktif</p>
    </div>

    <!-- Measurements Table -->
    <div class="measurements-table" v-if="selectedChild">
      <div class="table-header">
        <h3>📋 Riwayat Pengukuran</h3>
        <button class="add-btn" @click="addRandomData">➕ Tambah Data</button>
      </div>

      <div class="table-container">
        <table>
          <thead>
            <tr>
              <th>Tanggal</th>
              <th>Umur</th>
              <th>BB (kg)</th>
              <th>TB (cm)</th>
              <th>BB/U</th>
              <th>TB/U</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            <tr v-for="item in currentMeasurements" :key="item.id">
              <td>{{ formatDate(item.date) }}</td>
              <td>{{ item.age }} bln</td>
              <td :class="getBBClass(item)">{{ item.bb.toFixed(2) }}</td>
              <td :class="getTBClass(item)">{{ item.tb.toFixed(1) }}</td>
              <td :class="`status-${getStatusClass(item.bbStatus)}`">
                {{ item.bbStatus }}
              </td>
              <td :class="`status-${getStatusClass(item.tbStatus)}`">
                {{ item.tbStatus }}
              </td>
              <td>
                <span :class="`badge ${getOverallClass(item)}`">
                  {{ getStatusEmoji(item) }}
                </span>
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  </div>
</template>

<script>
import { Chart, registerables } from "chart.js";
Chart.register(...registerables);

export default {
  name: "GrafikPertumbuhan",
  data() {
    return {
      selectedChild: "",
      chartView: "dual",
      growthChart: null,
      bbChart: null,
      tbChart: null,
      childrenData: [
        { id: "bima", name: "Bima Santoso", age: 28 },
        { id: "sari", name: "Sari Nurhaliza", age: 19 },
        { id: "riko", name: "Riko Pratama", age: 36 },
      ],
      measurementsData: {
        bima: [
          {
            id: 1,
            date: "2025-09-01",
            age: 24,
            bb: 9.2,
            tb: 73.5,
            bbStatus: "Normal",
            tbStatus: "Normal",
          },
          {
            id: 2,
            date: "2025-10-01",
            age: 27,
            bb: 10.1,
            tb: 76.8,
            bbStatus: "Normal",
            tbStatus: "Normal",
          },
          {
            id: 3,
            date: "2025-11-01",
            age: 28,
            bb: 10.5,
            tb: 78.2,
            bbStatus: "Risiko Rendah",
            tbStatus: "Normal",
          },
        ],
        sari: [
          {
            id: 1,
            date: "2025-10-01",
            age: 15,
            bb: 7.8,
            tb: 68.2,
            bbStatus: "Normal",
            tbStatus: "Risiko Sedang",
          },
          {
            id: 2,
            date: "2025-11-15",
            age: 19,
            bb: 8.9,
            tb: 72.1,
            bbStatus: "Normal",
            tbStatus: "Normal",
          },
        ],
        riko: [
          {
            id: 1,
            date: "2025-08-01",
            age: 32,
            bb: 12.3,
            tb: 85.4,
            bbStatus: "Normal",
            tbStatus: "Normal",
          },
          {
            id: 2,
            date: "2025-10-01",
            age: 36,
            bb: 13.1,
            tb: 88.7,
            bbStatus: "Normal",
            tbStatus: "Risiko Rendah",
          },
        ],
      },
    };
  },
  computed: {
    currentMeasurements() {
      return this.measurementsData[this.selectedChild] || [];
    },
    latestMeasurement() {
      const data = this.currentMeasurements;
      return data[data.length - 1];
    },
    latestBB() {
      return this.latestMeasurement?.bb;
    },
    latestTB() {
      return this.latestMeasurement?.tb;
    },
    latestStatus() {
      const item = this.latestMeasurement;
      if (!item) return "";
      return item.bbStatus.includes("Risiko") ||
        item.tbStatus.includes("Risiko")
        ? item.bbStatus.includes("Tinggi") || item.tbStatus.includes("Tinggi")
          ? "danger"
          : "warning"
        : "normal";
    },
    latestStatusLabel() {
      const status = this.latestStatus;
      return status === "danger"
        ? "Perhatian!"
        : status === "warning"
        ? "Monitor"
        : "Normal";
    },
  },
  watch: {
    selectedChild() {
      this.$nextTick(() => this.renderCharts());
    },
    chartView() {
      this.$nextTick(() => this.renderCharts());
    },
  },
  mounted() {
    this.$nextTick(() => this.renderCharts());
  },
  beforeUnmount() {
    [this.growthChart, this.bbChart, this.tbChart].forEach((chart) => {
      if (chart) chart.destroy();
    });
  },
  methods: {
    loadChildData() {
      this.renderCharts();
    },
    setChartView(view) {
      this.chartView = view;
    },
    renderCharts() {
      if (!this.selectedChild) return;

      if (this.chartView === "dual") {
        this.renderDualCharts();
      } else {
        this.renderSingleChart();
      }
    },
    renderSingleChart() {
      if (this.growthChart) this.growthChart.destroy();

      const ctx = this.$refs.growthChart;
      const dataKey = this.chartView === "bb" ? "bb" : "tb";
      const color = this.chartView === "bb" ? "#10b981" : "#6366f1";

      this.growthChart = new Chart(ctx, {
        type: "line",
        data: {
          labels: this.currentMeasurements.map((m) => this.formatDate(m.date)),
          datasets: [
            {
              label: "Pertumbuhan",
              data: this.currentMeasurements.map((m) => m[dataKey]),
              borderColor: color,
              backgroundColor: `${color}20`,
              tension: 0.4,
              fill: true,
              pointBackgroundColor: color,
              pointBorderColor: "#fff",
              pointBorderWidth: 3,
              pointRadius: 8,
              pointHoverRadius: 10,
            },
          ],
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: { legend: { display: false } },
          scales: {
            y: {
              beginAtZero: false,
              grid: { color: "rgba(255,255,255,0.1)" },
              ticks: { color: "rgba(255,255,255,0.8)" },
            },
            x: {
              grid: { color: "rgba(255,255,255,0.1)" },
              ticks: { color: "rgba(255,255,255,0.8)" },
            },
          },
        },
      });
    },
    renderDualCharts() {
      // BB Chart
      if (this.bbChart) this.bbChart.destroy();
      const bbCtx = this.$refs.bbChart;
      this.bbChart = new Chart(bbCtx, {
        type: "line",
        data: {
          labels: this.currentMeasurements.map((m) => this.formatDate(m.date)),
          datasets: [
            {
              data: this.currentMeasurements.map((m) => m.bb),
              borderColor: "#10b981",
              backgroundColor: "#10b98120",
              tension: 0.4,
              fill: true,
              pointBackgroundColor: "#10b981",
              pointBorderColor: "#fff",
              pointBorderWidth: 2,
            },
          ],
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: { legend: { display: false } },
          scales: {
            y: {
              beginAtZero: false,
              grid: { color: "rgba(255,255,255,0.1)" },
              ticks: { color: "rgba(255,255,255,0.8)" },
            },
          },
        },
      });

      // TB Chart
      if (this.tbChart) this.tbChart.destroy();
      const tbCtx = this.$refs.tbChart;
      this.tbChart = new Chart(tbCtx, {
        type: "line",
        data: {
          labels: this.currentMeasurements.map((m) => this.formatDate(m.date)),
          datasets: [
            {
              data: this.currentMeasurements.map((m) => m.tb),
              borderColor: "#6366f1",
              backgroundColor: "#6366f120",
              tension: 0.4,
              fill: true,
              pointBackgroundColor: "#6366f1",
              pointBorderColor: "#fff",
              pointBorderWidth: 2,
            },
          ],
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: { legend: { display: false } },
          scales: {
            y: {
              beginAtZero: false,
              grid: { color: "rgba(255,255,255,0.1)" },
              ticks: { color: "rgba(255,255,255,0.8)" },
            },
          },
        },
      });
    },
    formatDate(dateStr) {
      return new Date(dateStr).toLocaleDateString("id-ID", {
        day: "numeric",
        month: "short",
        year: "numeric",
      });
    },
    getBBClass(item) {
      return this.getStatusClass(item.bbStatus);
    },
    getTBClass(item) {
      return this.getStatusClass(item.tbStatus);
    },
    getStatusClass(status) {
      if (status === "Normal") return "status-normal";
      if (status.includes("Risiko Rendah")) return "status-warning";
      if (status.includes("Risiko Sedang")) return "status-warning";
      if (status.includes("Risiko Tinggi")) return "status-danger";
      return "status-normal";
    },
    getOverallClass(item) {
      if (
        item.bbStatus.includes("Risiko Tinggi") ||
        item.tbStatus.includes("Risiko Tinggi")
      )
        return "danger";
      if (item.bbStatus.includes("Risiko") || item.tbStatus.includes("Risiko"))
        return "warning";
      return "success";
    },
    getStatusEmoji(item) {
      if (
        item.bbStatus.includes("Risiko Tinggi") ||
        item.tbStatus.includes("Risiko Tinggi")
      )
        return "🚨";
      if (item.bbStatus.includes("Risiko") || item.tbStatus.includes("Risiko"))
        return "⚠️";
      return "✅";
    },
    addRandomData() {
      const data = this.measurementsData[this.selectedChild];
      if (!data) return;

      const last = data[data.length - 1];
      const newData = {
        id: Date.now(),
        date: new Date().toISOString().split("T")[0],
        age: last.age + 1,
        bb: (last.bb + (Math.random() - 0.5) * 0.5).toFixed(2),
        tb: (last.tb + 0.8 + (Math.random() - 0.5) * 0.3).toFixed(1),
        bbStatus: Math.random() > 0.7 ? "Risiko Rendah" : "Normal",
        tbStatus: Math.random() > 0.8 ? "Risiko Sedang" : "Normal",
      };

      data.push(newData);
      this.renderCharts();
    },
  },
};
</script>

