<template>
  <div class="login-wrapper">
    <div class="login-card">
      <h2>Welcome Back</h2>
      <p class="subtitle">Masuk tanpa perlu daftar</p>

      <input type="text" v-model="username" placeholder="Username (bebas)" />

      <input
        type="password"
        v-model="password"
        placeholder="Password (bebas)"
      />

      <button :disabled="loading" @click="login">
        {{ loading ? "Logging in..." : "Login" }}
      </button>

      <p v-if="error" class="error">{{ error }}</p>
    </div>
  </div>
</template>

<script>
export default {
  name: "LoginPage",
  data() {
    return {
      username: "",
      password: "",
      error: "",
      loading: false,
    };
  },
  methods: {
    login() {
      if (!this.username || !this.password) {
        this.error = "Username dan password wajib diisi";
        return;
      }

      this.error = "";
      this.loading = true;

      setTimeout(() => {
        localStorage.setItem("isLogin", "true");
        localStorage.setItem("username", this.username);
        this.$router.push("/dashboard");
      }, 800);
    },
  },
};
</script>

