<script>
export default {
  name: "GlassDashboard",
  data() {
    return {
      isSidebarOpen: false,
      menuItems: [
        {
          path: "/dashboard",
          label: "Dashboard",
          icon: "📊",
          iconBg: "#6366f1",
        },
        {
          path: "/dashboard/input-anak",
          label: "Data Anak",
          icon: "👶",
          iconBg: "#10b981",
        },
        {
          path: "/dashboard/video-edukasi",
          label: "Edukasi",
          icon: "🎥",
          iconBg: "#f59e0b",
        },
        {
          path: "/dashboard/kalkulator-gizi",
          label: "Kalkulator",
          icon: "⚖️",
          iconBg: "#8b5cf6",
        },
        {
          path: "/dashboard/grafik-bb-tb",
          label: "Grafik",
          icon: "📈",
          iconBg: "#ef4444",
        },
      ],
    };
  },
  computed: {
    username() {
      return localStorage.getItem("username") || "User";
    },
    pageTitle() {
      const path = this.$route.path.split("/").pop() || "dashboard";
      const titles = {
        "input-anak": "Input Data Anak",
        "video-edukasi": "Video Edukasi",
        "kalkulator-gizi": "Kalkulator Gizi",
        "grafik-bb-tb": "Grafik Pertumbuhan",
      };
      return titles[path] || "Dashboard Utama";
    },
    isMobile() {
      return window.innerWidth < 768;
    },
  },
  methods: {
    toggleSidebar() {
      this.isSidebarOpen = !this.isSidebarOpen;
    },
    closeSidebar() {
      this.isSidebarOpen = false;
    },
    handleNavClick() {
      this.closeSidebar();
    },
    logout() {
      localStorage.removeItem("isLogin");
      localStorage.removeItem("username");
      this.$router.push("/");
    },
  },
  mounted() {
    window.addEventListener("resize", () => {
      if (window.innerWidth >= 1200) {
        this.isSidebarOpen = true;
      } else {
        this.isSidebarOpen = false;
      }
    });
  },
};
</script>

